import NoticeCard from "../components/NoticeCard";
import { useAccessibility } from "intelliaccess-framework";

const notices = [
  { id: 1, title: "Exam Schedule Released", content: "Check the exam dates on the student portal." },
  { id: 2, title: "Holiday Notice", content: "College will remain closed on Monday for a public holiday." },
  { id: 3, title: "Fee Payment Reminder", content: "Last date for fee payment is the 5th of next month." }
];

function Notices() {
  const { profile } = useAccessibility();

  let styles = {
    fontSize: "16px",
    letterSpacing: "normal",
    lineHeight: "normal",
    fontFamily: "inherit",
    backgroundColor: "white",
    color: "black"
  };

  if (profile === "lowVision") {
    styles.fontSize = "22px";
  }

 if (profile === "dyslexia") {
  styles.letterSpacing = "2px";
  styles.wordSpacing = "4px";
  styles.lineHeight = "2";
  styles.fontFamily = "'Lexend', sans-serif";
  styles.fontSize = "19px";
  styles.backgroundColor = "#fdf6e3"; // soft cream background - reduces visual stress, common dyslexia practice
}
  if (profile === "colourBlind") {
    styles.backgroundColor = "#000000";
    styles.color = "#FFFF00";
  }

  if (profile === "elderly") {
    styles.fontSize = "24px";
    styles.lineHeight = "1.6";
  }

  return (
    <div className="notices-container" style={styles}>
      <h1>Notices</h1>
      {notices.map((notice) => (
        <NoticeCard key={notice.id} title={notice.title} content={notice.content} elderly={profile === "elderly"} />
      ))}
    </div>
  );
}

export default Notices;
